-- 20-demo-localization-mz.sql  (HCM 2.1)
-- Source: hcm-demo cluster, tenant 'demo', pulled LIVE 2026-08-20 via
--   POST https://hcm-demo.digit.org/localization/messages/v1/_search?tenantId=demo&locale=<locale>
-- Substitution: tenant demo->mz, locale en_DEMO/pt_DEMO/fr_DEMO -> en_MZ/pt_MZ/fr_MZ.
--   module / code / message are carried VERBATIM (no text substitution).
--
-- INCLUDED: 179916 messages, 78 modules, 3 locales
--   (64095 en_MZ / 57800 pt_MZ / 58021 fr_MZ)
--
--   STATIC          68178  25 reusable UI-label modules.
--   BASE_TEMPLATE  107245  49 hcm-base-<module>-<projectType> app-config label templates.
--                          project-factory campaignUtils.ts:3173-3175 builds
--                            baseKey    = `hcm-base-${moduleName}-${projectType}`
--                            updatedKey = `hcm-${moduleName}-${campaignNumber}`
--                          and upsertLocalisations() COPIES base -> per-campaign at campaign creation.
--                          Nothing writes the hcm-base-* rows at runtime (they originate as committed
--                          JSON in DIGIT-Frontend health/configs/Localisations/), and a missing base
--                          module fails SILENTLY (campaignUtils.ts:3111-3132 catch->continue, and an
--                          empty message list yields an empty copy loop). Without these rows every
--                          campaign created on a fresh install renders RAW LABEL CODES in the app.
--   DSS              4493  hcm-dss (all) + rainmaker-hcm-dss STATIC labels only.
--                          DSS_TB_* / COMMON_MASTERS_* rows are excluded: they are identity mappings
--                          (code suffix == message) generated from uploaded boundary place names.
--
-- EXCLUDED deliberately:
--   hcm-boundary-*        regenerated unconditionally on boundary upload (boundaryUtils.ts:512-519),
--                         and dataset-specific to demo's own hierarchies.
--   hcm-<module>-CMP-*    per-campaign copies, regenerated from the BASE_TEMPLATE rows above.
--
-- Deduped: 0 exact (locale,module,code) duplicates + 376 whitespace-padded twins.
-- ON CONFLICT (tenantid,locale,module,code) DO **UPDATE** SET message = EXCLUDED.message.
--   On an EMPTY database this is identical to DO NOTHING (there is nothing to conflict with), so it is
--   safe for a fresh one-click install. On an EXISTING cluster it is what makes the tenant actually
--   CONVERGE on demo: with DO NOTHING, any label already present with a stale/divergent message was
--   silently kept forever and the tenant could never be brought back in line with demo.
-- Re-running is idempotent (the second run rewrites the same values).
-- POST-APPLY: kubectl exec -n backbone deploy/redis -- redis-cli DEL messages computedMessages

-- REQUIRED PRE-STEP -----------------------------------------------------------------------------
-- egov-localization migration V20170502122717 creates message.message as varchar(500), but demo
-- itself stores messages up to 543 characters (16 rows: hcm-admin-schemas README text and
-- digit-ui privacy-policy text, in pt/fr). A fresh one-click install therefore CANNOT load this
-- data without widening the column first - the insert aborts with
--   ERROR: value too long for type character varying(500)
-- Widening only; no data loss; safe to re-run.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_name = 'message' AND column_name = 'message'
               AND character_maximum_length IS NOT NULL
               AND character_maximum_length < 1000) THEN
    ALTER TABLE message ALTER COLUMN message TYPE varchar(1000);
  END IF;
END $$;
-- -----------------------------------------------------------------------------------------------

