(gen_random_uuid()::text,'mz','en_MZ','hcm-admin-schemas','FACILITYWITHBOUNDARY_README_HEADER_2_SUB_2_DESC_2','Step 2: In this step the user will have to add entries in the Facility Usage column with valid entries being either Active or Inactive where the user can set the usage for a facility to Active if the facility is being is used for a campaign or else can be set to Inactive. The inputs in the Facility Usage column need to be added for all entries.',1,now(),1,now()),
