(gen_random_uuid()::text,'mz','en_MZ','hcm-campaignmanager','ATTENDANCE_REGISTER_README_STEP_2','Each row in the template represents one attendance register. Fill in the boundary columns from left to right — for example, State, then District, then the lowest level you want the register created at. You must fill at least one boundary column per row; rows with no boundary filled will be rejected. The register will be created at the lowest boundary level you have filled in.',1,now(),1,now()),
