(gen_random_uuid()::text,'mz','en_MZ','hcm-campaignmanager','MODULE_DESCRIPTION_REGISTRATION','Register eligible children for the campaign and capture all required demographic and caregiver details. During field visits, record the delivery and follow-up needs.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','hcm-campaignmanager','MODULE_DESCRIPTION_REGISTRATION-DELIVERY','Register beneficiaries for bednet distribution campaigns & record household-level bednet deliveries during the campaign.',1,now(),1,now()),
