(gen_random_uuid()::text,'mz','en_MZ','rainmaker-common','CCF_PP_DO_WE_COLLECT_THIS_DATA_INFO_LABEL','We collect data directly from you (when you use our services) as and when you register and login into the app/website. We may also collect data from Union, State, and Local governments, including their agents/employees, as well as receive data that is available openly for public use.',1,now(),1,now()),
