(gen_random_uuid()::text,'mz','en_MZ','rainmaker-common','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_2_LABEL','You may delete your account any time you wish. In case of deletion, we will remove all your PII  from the system, so that it is not visible and/or accessible from any regular operation. However, the PII may be retained in an encrypted manner for the purpose of legal requirements/compliances AS PER UNION / STATE / ULB LAWS from the date of deletion/termination.',1,now(),1,now()),
