(gen_random_uuid()::text,'mz','en_MZ','rainmaker-common','CCF_PP_DO_WE_STORE_THIS_DATA_INFO_4_LABEL','If you simply delete/remove the application from your mobile device but do not delete your profile or unregister yourself from the app/website, you shall continue to be a registered user of the app and we shall continue to send you all communications that you have opted for unless and until you opt-out of such communications, or AS PER UNION / STATE / ULB LAW.',1,now(),1,now()),
