(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_BEDNETS_COVERAGE_CUMULATIVE_ONE','Bednets coverage represents the percentage of bednets distributed against the targeted distribution as per the microplan. This metric helps to evaluate the efficiency and effectiveness of the bednet distribution campaign.',1,now(),1,now()),
