(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_BEDNETS_DISTRIBUTED_DATE_RANGE_TWO','The calculation is performed by summing the quantity of bednets distributed for all households within the selected boundary and date range. The result is the total number of bednets distributed for the selected date range.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_BEDNETS_NOT_DELIVERED','Bed Nets Not Delivered',1,now(),1,now()),
