(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_BEDNETS_TARGETED_DATE_RANGE','Bed Nets Targeted (For selected date range)',1,now(),1,now()),
