(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_COMPLAINTS','Complaints',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_COMPLAINTS_FIVE','Overall, this visualization provides a quick and easy way to understand the number of complaints received and their current status, allowing for better monitoring and management of complaints for the boundary.',1,now(),1,now()),
