(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_COMPLAINTS_THREE','Each slice of the pie chart represents the percent of complaints for a particular status (Open, Resolved, or Rejected) for the selected province / district and date range. The boundary data will be as per the user role, which is national and provincial for the selected province.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_COMPLAINTS_TWO','The complaints data will be sourced from the Complaints module in the mobile app, and the boundary data will be obtained from the MDMS. The pie chart center will display the total number of complaints created for the selected province or district (as per the user role ) and the date range.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_DATA_SYNC','Data Sync',1,now(),1,now()),
