(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_HOUSEHOLDS_VISITED_DATE_RANGE_TWO','At the National and Provincial role level, the calculation is the sum of households visited for each district within the boundary for the selected date range.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','en_MZ','rainmaker-hcm-dss','DSS_CALCULATION_OVERVIEW_HOUSEHOLD_COVERAGE_RANKING','Household Coverage Ranking',1,now(),1,now()),
