(gen_random_uuid()::text,'mz','fr_MZ','digit-privacy-policy','PRIVACY_HEADER_1_SUB_1_DESC_2','HCM Console est un logiciel utilisé pour configurer et gérer des campagnes de santé publique. Il repose sur la plateforme DIGIT, développée et maintenue par la Fondation eGov.',1,now(),1,now()),
