(gen_random_uuid()::text,'mz','fr_MZ','digit-privacy-policy','PRIVACY_HEADER_1_SUB_1_DESC_4','Vous consultez cette politique car vous êtes un utilisateur de la console HCM.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','fr_MZ','digit-privacy-policy','PRIVACY_HEADER_1_SUB_1_DESC_5','Cela peut s''expliquer par le fait que vous configurez des campagnes, gérez les opérations de campagne ou accédez à la console dans le cadre de votre travail.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','fr_MZ','digit-privacy-policy','PRIVACY_HEADER_1_SUB_1_DESC_6','Lorsque vous utilisez la console HCM, des données vous concernant, pouvant inclure des informations personnelles identifiables (IPI), peuvent être collectées, stockées, traitées, utilisées et partagées.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','fr_MZ','digit-privacy-policy','PRIVACY_HEADER_1_SUB_1_DESC_7','Cette politique décrit les fondements de cette politique, la manière dont elle est mise en œuvre et vos droits à cet égard.',1,now(),1,now()),
