(gen_random_uuid()::text,'mz','fr_MZ','hcm-base-inventory-oncho','MODULE_DESCRIPTION_REGISTRATION','Inscrivez les enfants éligibles à la campagne et capturez tous les détails démographiques et de tuteurs requis. Lors des visites sur le terrain, enregistrez les besoins en matière de livraison et de suivi.',1,now(),1,now()),
(gen_random_uuid()::text,'mz','fr_MZ','hcm-base-inventory-oncho','MODULE_DESCRIPTION_REGISTRATION-DELIVERY','Enregistrez les bénéficiaires des campagnes de distribution de moustiquaires et enregistrez les livraisons de moustiquaires au niveau des ménages pendant la campagne.',1,now(),1,now()),
