(gen_random_uuid()::text,'mz','fr_MZ','hcm-base-registration-oncho','MODULE_DESCRIPTION_HFREFERRAL','Enregistrez et gérez les références pour les enfants qui nécessitent une évaluation ou un traitement plus approfondi. Saisissez les raisons de la référence, telles que les contre-indications, les effets indésirables ou les signes de danger, et suivez l''achèvement du traitement dans l''établissement de santé désigné.',1,now(),1,now()),
